function validate(input) {
  const [functions, x] = input;
  if (!Array.isArray(functions) || functions.length > 1000) return 'Give a list of at most 1000 functions.';
  if (!Number.isInteger(x) || x < -1000 || x > 1000) return 'x must be an integer from -1000 to 1000.';
  const pattern = /^(x|-?\d+) ([-+*]) (x|-?\d+)$/;
  for (const text of functions) {
    const match = typeof text === 'string' ? text.match(pattern) : null;
    if (!match) return 'Write each function as "a op b", for example "x + 1" or "2 * x".';
    for (const token of [match[1], match[3]]) {
      if (token !== 'x' && Math.abs(Number(token)) > 1000) return 'Constants must be from -1000 to 1000.';
    }
  }
  let value = x;
  for (let i = functions.length - 1; i >= 0; i--) {
    const [a, op, b] = functions[i].split(' ');
    const left = a === 'x' ? value : Number(a), right = b === 'x' ? value : Number(b);
    value = op === '+' ? left + right : op === '-' ? left - right : left * right;
    if (Math.abs(value) > 1e15) return 'The values grow too large: keep every intermediate result within 10^15.';
  }
  return null;
}

