function adapt(input, solve, kit) {
  const [functions, x] = input;
  const term = (token, value) => (token === 'x' ? value : Number(token));
  const real = functions.map((text, i) => {
    const [a, op, b] = text.split(' ');
    return (value) => {
      const left = term(a, value), right = term(b, value);
      let result = op === '+' ? left + right : op === '-' ? left - right : left * right;
      if (result === 0) result = 0; // no -0
      kit.trace(`functions[${i}] = ${text} turns ${value} into ${result}`);
      return result;
    };
  });
  const fn = solve(real);
  if (typeof fn !== 'function') throw new Error('compose must return a function.');
  kit.trace(`fn(${x}) is called`);
  const answer = fn(x);
  kit.trace(`fn(${x}) returns ${answer}`);
  return answer;
}

