function generate(rand, size) {
  const small = size === 'small';
  const count = small ? Math.floor(rand() * 6) : 1000;
  const range = small ? 10 : 1000;
  const x = Math.floor(rand() * (2 * range + 1)) - range;
  const bound = small ? 1e6 : 1e12;
  const evaluate = (text, value) => {
    const [a, op, b] = text.split(' ');
    const left = a === 'x' ? value : Number(a), right = b === 'x' ? value : Number(b);
    return op === '+' ? left + right : op === '-' ? left - right : left * right;
  };
  // Build the functions in the order they are applied (rightmost first), keeping values bounded.
  const applied = [];
  let value = x;
  for (let i = 0; i < count; i++) {
    const constant = Math.floor(rand() * (range + 1));
    const factor = [-2, -1, 2, 3][Math.floor(rand() * 4)];
    const options = [`x + ${constant}`, `x - ${constant}`, `${constant} - x`, `${factor} * x`, `x * ${factor}`, 'x * x'];
    let text = options[Math.floor(rand() * options.length)];
    if (Math.abs(evaluate(text, value)) > bound) text = value > 0 ? `x - ${constant}` : `x + ${constant}`;
    value = evaluate(text, value);
    applied.push(text);
  }
  return [applied.reverse(), x];
}
